+  lv_draw_arc_dsc_t arc;
+  lv_color_t color;
+  int32_t cx;
+  int32_t cy;
+
+  if (state == NULL || layer == NULL || lv_event_get_code(event) !=
+      LV_EVENT_DRAW_MAIN)
+    return;
+
