+static void vs_network_wifi_event(enum bk7258_wifi_event_e event,
+                                  unsigned int value, void *arg)
+{
+  struct vs_network_s *network = arg;
+
+  if (network == NULL)
+    {
+      return;
+    }
+
+  pthread_mutex_lock(&network->event_lock);
+  if (event == BK7258_WIFI_EVENT_STA_CONNECTED ||
+      event == BK7258_WIFI_EVENT_STA_DISCONNECTED)
+    {
+      network->wifi_event = true;
+      network->sta_connected = event == BK7258_WIFI_EVENT_STA_CONNECTED;
+      network->sta_disconnect_reason = network->sta_connected ? 0 :
+                                       (int)value;
+    }
+  else if (event == BK7258_WIFI_EVENT_AP_CLIENTS_CHANGED)
+    {
+      network->ap_client_event = true;
+      network->ap_client_count = value > UINT8_MAX ? UINT8_MAX :
+                                                       (uint8_t)value;
+    }
+  else if (event == BK7258_WIFI_EVENT_AP_STOPPED)
+    {
+      network->ap_client_event = true;
+      network->ap_client_count = 0;
+    }
+  pthread_mutex_unlock(&network->event_lock);
+}
+
+static int vs_network_scan_ssid(struct vs_network_s *network)
+{
+  struct wapi_list_s list;
+  struct wapi_scan_info_s *info;
+  int attempt;
+  int ret;
+
+  ret = wapi_scan_init(network->sock, "wlan0", network->config.sta_ssid);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  for (attempt = 0; attempt < VS_SCAN_POLLS; attempt++)
+    {
+      ret = wapi_scan_stat(network->sock, "wlan0");
+      if (ret <= 0)
+        {
+          break;
+        }
+
+      usleep(VS_SCAN_POLL_MS * 1000);
+    }
+
+  if (ret != 0)
+    {
+      return ret < 0 ? ret : -ETIMEDOUT;
+    }
+
+  memset(&list, 0, sizeof(list));
+  ret = wapi_scan_coll(network->sock, "wlan0", &list);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  ret = -ENETUNREACH;
+  for (info = list.head.scan; info != NULL; info = info->next)
+    {
+      if (info->has_essid &&
+          strcmp(info->essid, network->config.sta_ssid) == 0)
+        {
+          ret = 0;
+          break;
+        }
+    }
+
+  wapi_scan_coll_free(&list);
+  return ret;
+}
